import{_ as e,o as d,c as l,aU as r,bf as a}from"./chunks/framework.BWaOKJaB.js";const o=JSON.parse('{"title":"Numpy 速查表","description":"","frontmatter":{},"headers":[],"relativePath":"技术/后端/Numpy.md","filePath":"03.技术/02.后端/01.Numpy.md","lastUpdated":0}'),n={name:"技术/后端/Numpy.md"};function i(s,t,g,h,x,p){return d(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="numpy-速查表" tabindex="-1">Numpy 速查表 <a class="header-anchor" href="#numpy-速查表" aria-label="Permalink to “Numpy 速查表”">​</a></h1><div class="info custom-block"><p class="custom-block-title">前言</p><p>Numpy 是 Python 中用于科学计算的基础库，提供了多维数组对象和各种派生对象（如掩码数组和矩阵），以及用于快速操作数组的函数。它也是 SciPy 生态系统的基础，SciPy 提供了更多的科学计算功能。使用 Numpy 可以快速实现数组的计算、统计、排序、过滤、聚合等高效的向量化操作。</p><p>在学习 Numpy 之前首先要建立一个向量化概念，什么是向量化操作？</p><p>向量化操作是指使用Numpy提供的内置函数直接对整个数组进行运算，而不是使用Python循环逐个处理元素。这样做的好处是速度快很多——通常快10-100倍。</p><p>简单来说，向量化就是让计算机一次处理整个数组，而不是一个一个处理，这样就能发挥计算机的并行处理能力，速度快得多。特别是在科学计算领域和图像处理中，科学计算任务的矩阵运算和图像本身就是多维数组，必须用向量化才能有好的性能！使用向量化操作的代码看起来更简洁、更易读，而且更符合Python的编程风格。</p></div><h2 id="快速创建数组" tabindex="-1">快速创建数组 <a class="header-anchor" href="#快速创建数组" aria-label="Permalink to “快速创建数组”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">方法</th><th>描述</th><th style="text-align:right;">示例</th></tr></thead><tbody><tr><td style="text-align:left;">np.array()</td><td>创建一个数组</td><td style="text-align:right;">np.array([1, 2, 3, 4, 5])</td></tr><tr><td style="text-align:left;">np.zeros()</td><td>创建一个全0数组</td><td style="text-align:right;">np.zeros((3, 3))</td></tr><tr><td style="text-align:left;">np.ones()</td><td>创建一个全1数组</td><td style="text-align:right;">np.ones((3, 3))</td></tr><tr><td style="text-align:left;">np.empty()</td><td>创建一个空数组</td><td style="text-align:right;">np.empty((3, 3))</td></tr><tr><td style="text-align:left;">np.arange()</td><td>创建一个等差数组</td><td style="text-align:right;">np.arange(10)</td></tr><tr><td style="text-align:left;">np.linspace()</td><td>创建一个等差数组</td><td style="text-align:right;">np.linspace(0, 10, 5)</td></tr><tr><td style="text-align:left;">np.logspace()</td><td>创建一个对数数组</td><td style="text-align:right;">np.logspace(0, 2, 5)</td></tr><tr><td style="text-align:left;">np.random.rand()</td><td>创建一个随机数组</td><td style="text-align:right;">np.random.rand(3, 3)</td></tr></tbody></table><h2 id="常用属性与方法" tabindex="-1">常用属性与方法 <a class="header-anchor" href="#常用属性与方法" aria-label="Permalink to “常用属性与方法”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">常用方法</th><th>描述</th><th style="text-align:right;">示例</th></tr></thead><tbody><tr><td style="text-align:left;">np.shape</td><td>获取数组形状，返回一个元组，表示数组的维度</td><td style="text-align:right;">np.shape(arr)</td></tr><tr><td style="text-align:left;">np.ndim</td><td>获取数组维度，返回一个整数，表示数组的维度</td><td style="text-align:right;">np.ndim(arr)</td></tr><tr><td style="text-align:left;">np.size</td><td>获取数组元素个数，返回一个整数，表示数组的元素个数</td><td style="text-align:right;">np.size(arr)</td></tr><tr><td style="text-align:left;">np.dtype</td><td>获取数组元素类型，返回一个数据类型对象</td><td style="text-align:right;">np.dtype(arr)</td></tr><tr><td style="text-align:left;">np.astype()</td><td>转换数组元素类型，返回一个新数组</td><td style="text-align:right;">np.astype(arr, dtype)</td></tr><tr><td style="text-align:left;">np.reshape()</td><td>重塑数组形状，返回一个新数组</td><td style="text-align:right;">np.reshape(arr, newshape)</td></tr><tr><td style="text-align:left;">np.flatten()</td><td>展平数组，返回一个新数组</td><td style="text-align:right;">np.flatten(arr)</td></tr><tr><td style="text-align:left;">np.transpose()</td><td>转置数组，返回一个新数组</td><td style="text-align:right;">np.transpose(arr)</td></tr><tr><td style="text-align:left;">np.dot()</td><td>矩阵乘法，返回一个新数组</td><td style="text-align:right;">np.dot(arr1, arr2)</td></tr><tr><td style="text-align:left;">np.sum()</td><td>求和，返回一个整数</td><td style="text-align:right;">np.sum(arr)</td></tr><tr><td style="text-align:left;">np.mean()</td><td>求平均值，返回一个浮点数</td><td style="text-align:right;">np.mean(arr)</td></tr><tr><td style="text-align:left;">np.std()</td><td>求标准差，返回一个浮点数</td><td style="text-align:right;">np.std(arr)</td></tr><tr><td style="text-align:left;">np.max()</td><td>求最大值，返回一个浮点数</td><td style="text-align:right;">np.max(arr)</td></tr><tr><td style="text-align:left;">np.min()</td><td>求最小值，返回一个浮点数</td><td style="text-align:right;">np.min(arr)</td></tr></tbody></table><h2 id="数组运算" tabindex="-1">数组运算 <a class="header-anchor" href="#数组运算" aria-label="Permalink to “数组运算”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">运算符</th><th>描述</th><th style="text-align:right;">示例</th></tr></thead><tbody><tr><td style="text-align:left;">+</td><td>数组元素相加，返回一个新数组</td><td style="text-align:right;">arr1 + arr2</td></tr><tr><td style="text-align:left;">-</td><td>数组元素相减，返回一个新数组</td><td style="text-align:right;">arr1 - arr2</td></tr><tr><td style="text-align:left;">*</td><td>数组元素相乘，返回一个新数组</td><td style="text-align:right;">arr1 * arr2</td></tr><tr><td style="text-align:left;">/</td><td>数组元素相除，返回一个新数组</td><td style="text-align:right;">arr1 / arr2</td></tr><tr><td style="text-align:left;">**</td><td>数组元素幂运算，返回一个新数组</td><td style="text-align:right;">arr1 ** arr2</td></tr><tr><td style="text-align:left;">%</td><td>数组元素取模，返回一个新数组</td><td style="text-align:right;">arr1 % arr2</td></tr><tr><td style="text-align:left;">//</td><td>数组元素整除，返回一个新数组</td><td style="text-align:right;">arr1 // arr2</td></tr><tr><td style="text-align:left;">&amp;</td><td>数组元素按位与，返回一个新数组</td><td style="text-align:right;">arr1 &amp; arr2</td></tr><tr><td style="text-align:left;">|</td><td>数组元素按位或，返回一个新数组</td><td style="text-align:right;">arr1 | arr2</td></tr></tbody></table><ul><li>简单说说矩阵乘法的规则</li></ul><blockquote><p>规则：结果矩阵的第(i,j)位置 = 第一个矩阵的第i行 与 第二个矩阵的第j列 对应元素相乘后求和。这也有一种俗称叫点积运算。</p></blockquote><p>比如下面的例子：</p><p><img src="'+a+'" alt="numpy矩阵运算"></p><div class="tip custom-block"><p class="custom-block-title">重要概念</p><ul><li><p>必须满足维度要求：(m×n) × (n×p) = (m×p)</p><p>第一个矩阵的列数必须等于第二个矩阵的行数</p></li><li><p>不可交换：A × B ≠ B × A（矩阵乘法不满足交换律）</p></li></ul></div><h2 id="数组统计" tabindex="-1">数组统计 <a class="header-anchor" href="#数组统计" aria-label="Permalink to “数组统计”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">统计方法</th><th>描述</th><th style="text-align:right;">示例</th></tr></thead><tbody><tr><td style="text-align:left;">np.sum()</td><td>求和，返回一个整数</td><td style="text-align:right;">np.sum(arr)</td></tr><tr><td style="text-align:left;">np.mean()</td><td>求平均值，返回一个浮点数</td><td style="text-align:right;">np.mean(arr)</td></tr><tr><td style="text-align:left;">np.std()</td><td>求标准差，返回一个浮点数</td><td style="text-align:right;">np.std(arr)</td></tr><tr><td style="text-align:left;">np.max()</td><td>求最大值，返回一个浮点数</td><td style="text-align:right;">np.max(arr)</td></tr><tr><td style="text-align:left;">np.min()</td><td>求最小值，返回一个浮点数</td><td style="text-align:right;">np.min(arr)</td></tr></tbody></table><h2 id="数组排序" tabindex="-1">数组排序 <a class="header-anchor" href="#数组排序" aria-label="Permalink to “数组排序”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">排序方法</th><th>描述</th><th style="text-align:right;">示例</th></tr></thead><tbody><tr><td style="text-align:left;">np.sort()</td><td>排序，返回一个新数组</td><td style="text-align:right;">np.sort(arr)</td></tr><tr><td style="text-align:left;">np.argsort()</td><td>返回排序后的索引，返回一个新数组</td><td style="text-align:right;">np.argsort(arr)</td></tr><tr><td style="text-align:left;">np.lexsort()</td><td>返回排序后的索引，返回一个新数组</td><td style="text-align:right;">np.lexsort(arr)</td></tr><tr><td style="text-align:left;">np.searchsorted()</td><td>返回排序后的索引，返回一个新数组</td><td style="text-align:right;">np.searchsorted(arr, value)</td></tr><tr><td style="text-align:left;">np.partition()</td><td>返回排序后的索引，返回一个新数组</td><td style="text-align:right;">np.partition(arr, k)</td></tr><tr><td style="text-align:left;">np.argpartition()</td><td>返回排序后的索引，返回一个新数组</td><td style="text-align:right;">np.argpartition(arr, k)</td></tr></tbody></table><h2 id="数组过滤" tabindex="-1">数组过滤 <a class="header-anchor" href="#数组过滤" aria-label="Permalink to “数组过滤”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">过滤方法</th><th>描述</th><th style="text-align:right;">示例</th></tr></thead><tbody><tr><td style="text-align:left;">np.where()</td><td>返回满足条件的索引，返回一个新数组</td><td style="text-align:right;">np.where(condition)</td></tr><tr><td style="text-align:left;">np.nonzero()</td><td>返回满足条件的索引，返回一个新数组</td><td style="text-align:right;">np.nonzero(arr)</td></tr><tr><td style="text-align:left;">np.logical_and()</td><td>返回满足条件的索引，返回一个新数组</td><td style="text-align:right;">np.logical_and(arr1, arr2)</td></tr><tr><td style="text-align:left;">np.logical_or()</td><td>返回满足条件的索引，返回一个新数组</td><td style="text-align:right;">np.logical_or(arr1, arr2)</td></tr><tr><td style="text-align:left;">np.logical_not()</td><td>返回满足条件的索引，返回一个新数组</td><td style="text-align:right;">np.logical_not(arr)</td></tr><tr><td style="text-align:left;">np.logical_xor()</td><td>返回满足条件的索引，返回一个新数组</td><td style="text-align:right;">np.logical_xor(arr1, arr2)</td></tr><tr><td style="text-align:left;">np.logical_and()</td><td>返回满足条件的索引，返回一个新数组</td><td style="text-align:right;">np.logical_and(arr1, arr2)</td></tr><tr><td style="text-align:left;">np.logical_or()</td><td>返回满足条件的索引，返回一个新数组</td><td style="text-align:right;">np.logical_or(arr1, arr2)</td></tr><tr><td style="text-align:left;">np.logical_not()</td><td>返回满足条件的索引，返回一个新数组</td><td style="text-align:right;">np.logical_not(arr)</td></tr><tr><td style="text-align:left;">np.logical_xor()</td><td>返回满足条件的索引，返回一个新数组</td><td style="text-align:right;">np.logical_xor(arr1, arr2)</td></tr></tbody></table><h2 id="数组聚合" tabindex="-1">数组聚合 <a class="header-anchor" href="#数组聚合" aria-label="Permalink to “数组聚合”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">聚合方法</th><th>描述</th><th style="text-align:right;">示例</th></tr></thead><tbody><tr><td style="text-align:left;">np.sum()</td><td>数组元素求和，返回一个浮点数</td><td style="text-align:right;">np.sum(arr)</td></tr><tr><td style="text-align:left;">np.mean()</td><td>数组元素求平均值，返回一个浮点数</td><td style="text-align:right;">np.mean(arr)</td></tr><tr><td style="text-align:left;">np.std()</td><td>数组元素求标准差，返回一个浮点数</td><td style="text-align:right;">np.std(arr)</td></tr><tr><td style="text-align:left;">np.max()</td><td>数组元素求最大值，返回一个浮点数</td><td style="text-align:right;">np.max(arr)</td></tr><tr><td style="text-align:left;">np.min()</td><td>数组元素求最小值，返回一个浮点数</td><td style="text-align:right;">np.min(arr)</td></tr></tbody></table><h2 id="数组广播" tabindex="-1">数组广播 <a class="header-anchor" href="#数组广播" aria-label="Permalink to “数组广播”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">广播方法</th><th>描述</th><th style="text-align:right;">示例</th></tr></thead><tbody><tr><td style="text-align:left;">np.broadcast()</td><td>广播数组</td><td style="text-align:right;">np.broadcast(arr1, arr2)</td></tr><tr><td style="text-align:left;">np.broadcast_to()</td><td>广播数组</td><td style="text-align:right;">np.broadcast_to(arr, shape)</td></tr><tr><td style="text-align:left;">np.broadcast_arrays()</td><td>广播数组</td><td style="text-align:right;">np.broadcast_arrays(arr1, arr2)</td></tr><tr><td style="text-align:left;">np.broadcast_to()</td><td>广播数组</td><td style="text-align:right;">np.broadcast_to(arr, shape)</td></tr></tbody></table><h2 id="数组索引" tabindex="-1">数组索引 <a class="header-anchor" href="#数组索引" aria-label="Permalink to “数组索引”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">索引方法</th><th>描述</th><th style="text-align:right;">示例</th></tr></thead><tbody><tr><td style="text-align:left;">np.index()</td><td>索引数组</td><td style="text-align:right;">np.index(arr, index)</td></tr><tr><td style="text-align:left;">np.index_exp()</td><td>索引数组</td><td style="text-align:right;">np.index_exp(arr, index)</td></tr><tr><td style="text-align:left;">np.index_exp()</td><td>索引数组</td><td style="text-align:right;">np.index_exp(arr, index)</td></tr></tbody></table><h2 id="数组拼接" tabindex="-1">数组拼接 <a class="header-anchor" href="#数组拼接" aria-label="Permalink to “数组拼接”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">拼接方法</th><th>描述</th><th style="text-align:right;">示例</th></tr></thead><tbody><tr><td style="text-align:left;">np.concatenate()</td><td>拼接数组</td><td style="text-align:right;">np.concatenate(arr1, arr2)</td></tr><tr><td style="text-align:left;">np.stack()</td><td>拼接数组</td><td style="text-align:right;">np.stack(arr1, arr2)</td></tr><tr><td style="text-align:left;">np.hstack()</td><td>拼接数组</td><td style="text-align:right;">np.hstack(arr1, arr2)</td></tr><tr><td style="text-align:left;">np.vstack()</td><td>拼接数组</td><td style="text-align:right;">np.vstack(arr1, arr2)</td></tr><tr><td style="text-align:left;">np.dstack()</td><td>拼接数组</td><td style="text-align:right;">np.dstack(arr1, arr2)</td></tr><tr><td style="text-align:left;">np.column_stack()</td><td>拼接数组</td><td style="text-align:right;">np.column_stack(arr1, arr2)</td></tr><tr><td style="text-align:left;">np.row_stack()</td><td>拼接数组</td><td style="text-align:right;">np.row_stack(arr1, arr2)</td></tr></tbody></table><h2 id="数组分割" tabindex="-1">数组分割 <a class="header-anchor" href="#数组分割" aria-label="Permalink to “数组分割”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">分割方法</th><th>描述</th><th style="text-align:right;">示例</th></tr></thead><tbody><tr><td style="text-align:left;">np.split()</td><td>分割数组</td><td style="text-align:right;">np.split(arr, indices_or_sections)</td></tr><tr><td style="text-align:left;">np.hsplit()</td><td>分割数组</td><td style="text-align:right;">np.hsplit(arr, indices_or_sections)</td></tr><tr><td style="text-align:left;">np.vsplit()</td><td>分割数组</td><td style="text-align:right;">np.vsplit(arr, indices_or_sections)</td></tr><tr><td style="text-align:left;">np.dsplit()</td><td>分割数组</td><td style="text-align:right;">np.dsplit(arr, indices_or_sections)</td></tr><tr><td style="text-align:left;">np.column_split()</td><td>分割数组</td><td style="text-align:right;">np.column_split(arr, indices_or_sections)</td></tr><tr><td style="text-align:left;">np.row_split()</td><td>分割数组</td><td style="text-align:right;">np.row_split(arr, indices_or_sections)</td></tr></tbody></table><h2 id="数组转置" tabindex="-1">数组转置 <a class="header-anchor" href="#数组转置" aria-label="Permalink to “数组转置”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">转置方法</th><th>描述</th><th style="text-align:right;">示例</th></tr></thead><tbody><tr><td style="text-align:left;">np.transpose()</td><td>转置数组</td><td style="text-align:right;">np.transpose(arr)</td></tr><tr><td style="text-align:left;">np.T</td><td>转置数组</td><td style="text-align:right;">np.T(arr)</td></tr><tr><td style="text-align:left;">np.swapaxes()</td><td>转置数组</td><td style="text-align:right;">np.swapaxes(arr, axis1, axis2)</td></tr><tr><td style="text-align:left;">np.rollaxis()</td><td>转置数组</td><td style="text-align:right;">np.rollaxis(arr, axis, start)</td></tr><tr><td style="text-align:left;">np.moveaxis()</td><td>转置数组</td><td style="text-align:right;">np.moveaxis(arr, source, destination)</td></tr><tr><td style="text-align:left;">np.roll()</td><td>转置数组</td><td style="text-align:right;">np.roll(arr, shift, axis=None)</td></tr><tr><td style="text-align:left;">np.move()</td><td>转置数组</td><td style="text-align:right;">np.move(arr, source, destination)</td></tr><tr><td style="text-align:left;">np.rollaxis()</td><td>转置数组</td><td style="text-align:right;">np.rollaxis(arr, axis, start)</td></tr><tr><td style="text-align:left;">np.moveaxis()</td><td>转置数组</td><td style="text-align:right;">np.moveaxis(arr, source, destination)</td></tr></tbody></table><h2 id="数组裁剪" tabindex="-1">数组裁剪 <a class="header-anchor" href="#数组裁剪" aria-label="Permalink to “数组裁剪”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">裁剪方法</th><th>描述</th><th style="text-align:right;">示例</th></tr></thead><tbody><tr><td style="text-align:left;">np.clip()</td><td>裁剪数组</td><td style="text-align:right;">np.clip(arr, min, max)</td></tr><tr><td style="text-align:left;">np.compress()</td><td>裁剪数组</td><td style="text-align:right;">np.compress(condition, arr)</td></tr><tr><td style="text-align:left;">np.extract()</td><td>裁剪数组</td><td style="text-align:right;">np.extract(condition, arr)</td></tr><tr><td style="text-align:left;">np.put()</td><td>裁剪数组</td><td style="text-align:right;">np.put(arr, indices, values)</td></tr><tr><td style="text-align:left;">np.putmask()</td><td>裁剪数组</td><td style="text-align:right;">np.putmask(arr, mask, values)</td></tr><tr><td style="text-align:left;">np.fill()</td><td>裁剪数组</td><td style="text-align:right;">np.fill(arr, value)</td></tr><tr><td style="text-align:left;">np.seterr()</td><td>裁剪数组</td><td style="text-align:right;">np.seterr(all=&#39;ignore&#39;)</td></tr><tr><td style="text-align:left;">np.seterr()</td><td>裁剪数组</td><td style="text-align:right;">np.seterr(all=&#39;ignore&#39;)</td></tr></tbody></table><h2 id="数组函数" tabindex="-1">数组函数 <a class="header-anchor" href="#数组函数" aria-label="Permalink to “数组函数”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">函数</th><th>描述</th><th style="text-align:right;">示例</th></tr></thead><tbody><tr><td style="text-align:left;">np.sin()</td><td>正弦函数</td><td style="text-align:right;">np.sin(arr)</td></tr><tr><td style="text-align:left;">np.cos()</td><td>余弦函数</td><td style="text-align:right;">np.cos(arr)</td></tr><tr><td style="text-align:left;">np.tan()</td><td>正切函数</td><td style="text-align:right;">np.tan(arr)</td></tr><tr><td style="text-align:left;">np.arcsin()</td><td>反正弦函数</td><td style="text-align:right;">np.arcsin(arr)</td></tr><tr><td style="text-align:left;">np.arccos()</td><td>反余弦函数</td><td style="text-align:right;">np.arccos(arr)</td></tr><tr><td style="text-align:left;">np.arctan()</td><td>反正切函数</td><td style="text-align:right;">np.arctan(arr)</td></tr><tr><td style="text-align:left;">np.sinh()</td><td>双曲正弦函数</td><td style="text-align:right;">np.sinh(arr)</td></tr><tr><td style="text-align:left;">np.cosh()</td><td>双曲余弦函数</td><td style="text-align:right;">np.cosh(arr)</td></tr><tr><td style="text-align:left;">np.tanh()</td><td>双曲正切函数</td><td style="text-align:right;">np.tanh(arr)</td></tr><tr><td style="text-align:left;">np.sqrt()</td><td>平方根函数</td><td style="text-align:right;">np.sqrt(arr)</td></tr><tr><td style="text-align:left;">np.exp()</td><td>指数函数</td><td style="text-align:right;">np.exp(arr)</td></tr><tr><td style="text-align:left;">np.log()</td><td>对数函数</td><td style="text-align:right;">np.log(arr)</td></tr><tr><td style="text-align:left;">np.log10()</td><td>以10为底的对数函数</td><td style="text-align:right;">np.log10(arr)</td></tr><tr><td style="text-align:left;">np.log2()</td><td>以2为底的对数函数</td><td style="text-align:right;">np.log2(arr)</td></tr><tr><td style="text-align:left;">np.log1p()</td><td>以e为底的对数函数</td><td style="text-align:right;">np.log1p(arr)</td></tr><tr><td style="text-align:left;">np.log2p()</td><td>以2为底的对数函数</td><td style="text-align:right;">np.log2p(arr)</td></tr><tr><td style="text-align:left;">np.log10p()</td><td>以10为底的对数函数</td><td style="text-align:right;">np.log10p(arr)</td></tr></tbody></table><h2 id="数组应用" tabindex="-1">数组应用 <a class="header-anchor" href="#数组应用" aria-label="Permalink to “数组应用”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">应用方法</th><th>描述</th><th style="text-align:right;">示例</th></tr></thead><tbody><tr><td style="text-align:left;">np.apply_along_axis()</td><td>应用数组</td><td style="text-align:right;">np.apply_along_axis(func, axis, arr)</td></tr><tr><td style="text-align:left;">np.apply_over_axes()</td><td>应用数组</td><td style="text-align:right;">np.apply_over_axes(func, arr, axes)</td></tr><tr><td style="text-align:left;">np.apply_along_axis()</td><td>应用数组</td><td style="text-align:right;">np.apply_along_axis(func, axis, arr)</td></tr></tbody></table><h2 id="图片像素操作" tabindex="-1">图片像素操作 <a class="header-anchor" href="#图片像素操作" aria-label="Permalink to “图片像素操作”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">目标</th><th style="text-align:left;">代码</th></tr></thead><tbody><tr><td style="text-align:left;">整个图像变黑</td><td style="text-align:left;"><code>img[:, :, :]</code> = 0 或 <code>img[...] = 0</code></td></tr><tr><td style="text-align:left;">整个图像变白</td><td style="text-align:left;"><code>img[:, :, :] = 255</code></td></tr><tr><td style="text-align:left;">只清零某通道</td><td style="text-align:left;"><code>img[:, :, 0] = 0</code></td></tr><tr><td style="text-align:left;">乘以系数</td><td style="text-align:left;"><code>img *= 0.5</code></td></tr></tbody></table>',39)])])}const f=e(n,[["render",i]]);export{o as __pageData,f as default};
